1	// Package placement parses raw placement request bodies into the input
2	// object accepted by service.Accept. It is a standalone entry point: it has
3	// no dependency on the HTTP transport, opens no database, and performs no
4	// scheduling or writes. The HTTP API and direct callers share exactly these
5	// strict rules.
6	package placement
7	
8	import (
9		"bytes"
10		"encoding/json"
11		"errors"
12		"io"
13		"strconv"
14		"strings"
15	
16		"github.com/Bob-xisuke/orb-scheduler-core/internal/store"
17	)
18	
19	// ErrInvalidPlacementInput is the single sentinel returned for every parse
20	// failure: malformed JSON, a non-object root, trailing data, unknown or
21	// duplicate member names, missing required fields, explicit nulls, type or
22	// range errors, and duplicate node names. Callers classify failures with
23	// errors.Is; a failed parse never yields a partial input object.
24	var ErrInvalidPlacementInput = errors.New("invalid placement input")
25	
26	// ---------------------------------------------------------------------------
27	// Strict request parsing.
28	//
29	// The token walk below enforces, before anything is stored:
30	//   - the body is one JSON object with exactly the documented members,
31	//   - no unknown or duplicate member names at any level,
32	//   - no trailing data after the root object,
33	//   - every value has the declared JSON type and range (null is never accepted
34	//     where a value is required; omitted selector/labels default to {}),
35	//   - node names are unique.
36	// ---------------------------------------------------------------------------
37	
38	var topLevelFields = map[string]bool{
39		"namespace": true,
40		"name":      true,
41		"queue":     true,
42		"priority":  true,
43		"resources": true,
44		"selector":  true,
45		"nodes":     true,
46	}
47	
48	var resourceFields = map[string]bool{"cpu": true, "memory": true}
49	
50	var nodeFields = map[string]bool{
51		"name":   true,
52		"cpu":    true,
53		"memory": true,
54		"labels": true,
55	}
56	
57	// ParsePlacementInput decodes one placement request body. On success it
58	// returns the complete input object, ready for service.Accept: every input
59	// field keeps its submitted value, the node array keeps its order, omitted
60	// selector and node labels are filled as empty objects, and an empty nodes
61	// array stays an empty array. On any rule violation it returns nil and an
62	// error matching errors.Is(err, ErrInvalidPlacementInput).
63	func ParsePlacementInput(body []byte) (*store.Placement, error) {
64		dec := json.NewDecoder(bytes.NewReader(body))
65		dec.UseNumber()
66	
67		tok, err := dec.Token()
68		if err != nil {
69			return nil, ErrInvalidPlacementInput
70		}
71		if d, ok := tok.(json.Delim); !ok || d != '{' {
72			return nil, ErrInvalidPlacementInput
73		}
74	
75		p := &store.Placement{}
76		seen := map[string]bool{}
77		for dec.More() {
78			keyTok, err := dec.Token()
79			if err != nil {
80				return nil, ErrInvalidPlacementInput
81			}
82			key, ok := keyTok.(string)
83			if !ok || !topLevelFields[key] || seen[key] {
84				return nil, ErrInvalidPlacementInput
85			}
86			seen[key] = true
87	
88			var raw json.RawMessage
89			if err := dec.Decode(&raw); err != nil {
90				return nil, ErrInvalidPlacementInput
91			}
92	
93			switch key {
94			case "namespace", "name", "queue":
95				s, err := parseTrimmedString(raw)
96				if err != nil {
97					return nil, err
98				}
99				switch key {
100				case "namespace":
101					p.Namespace = s
102				case "name":
103					p.Name = s
104				case "queue":
105					p.Queue = s
106				}
107			case "priority":
108				n, err := parseBoundedInt(raw, 32)
109				if err != nil {
110					return nil, err
111				}
112				p.Priority = int32(n)
113			case "resources":
114				r, err := parseResources(raw)
115				if err != nil {
116					return nil, err
117				}
118				p.Resources = r
119			case "selector":
120				m, err := parseStringMap(raw)
121				if err != nil {
122					return nil, err
123				}
124				p.Selector = m
125			case "nodes":
126				nodes, err := parseNodes(raw)
127				if err != nil {
128					return nil, err
129				}
130				p.Nodes = nodes
131			}
132		}
133		if _, err := dec.Token(); err != nil {
134			return nil, ErrInvalidPlacementInput // closing '}'
135		}
136		if _, err := dec.Token(); !errors.Is(err, io.EOF) {
137			return nil, ErrInvalidPlacementInput // trailing data
138		}
139	
140		for _, required := range []string{"namespace", "name", "queue", "priority", "resources", "nodes"} {
141			if !seen[required] {
142				return nil, ErrInvalidPlacementInput
143			}
144		}
145		if p.Selector == nil {
146			p.Selector = map[string]string{}
147		}
148		return p, nil
149	}
