151	func parseResources(raw json.RawMessage) (store.Resources, error) {
152		var r store.Resources
153		obj, err := parseStrictObject(raw, resourceFields)
154		if err != nil {
155			return r, err
156		}
157		cpuRaw, ok := obj["cpu"]
158		if !ok {
159			return r, ErrInvalidPlacementInput
160		}
161		memoryRaw, ok := obj["memory"]
162		if !ok {
163			return r, ErrInvalidPlacementInput
164		}
165		cpu, err := parseBoundedInt(cpuRaw, 64)
166		if err != nil || cpu <= 0 {
167			return r, ErrInvalidPlacementInput
168		}
169		memory, err := parseBoundedInt(memoryRaw, 64)
170		if err != nil || memory <= 0 {
171			return r, ErrInvalidPlacementInput
172		}
173		return store.Resources{CPU: cpu, Memory: memory}, nil
174	}
175	
176	func parseNodes(raw json.RawMessage) ([]store.Node, error) {
177		if isNull(raw) {
178			return nil, ErrInvalidPlacementInput
179		}
180		dec := json.NewDecoder(bytes.NewReader(raw))
181		tok, err := dec.Token()
182		if err != nil {
183			return nil, ErrInvalidPlacementInput
184		}
185		if d, ok := tok.(json.Delim); !ok || d != '[' {
186			return nil, ErrInvalidPlacementInput
187		}
188	
189		nodes := []store.Node{}
190		names := map[string]bool{}
191		for dec.More() {
192			var elem json.RawMessage
193			if err := dec.Decode(&elem); err != nil {
194				return nil, ErrInvalidPlacementInput
195			}
196			obj, err := parseStrictObject(elem, nodeFields)
197			if err != nil {
198				return nil, err
199			}
200			nameRaw, ok := obj["name"]
201			if !ok {
202				return nil, ErrInvalidPlacementInput
203			}
204			cpuRaw, ok := obj["cpu"]
205			if !ok {
206				return nil, ErrInvalidPlacementInput
207			}
208			memoryRaw, ok := obj["memory"]
209			if !ok {
210				return nil, ErrInvalidPlacementInput
211			}
212			name, err := parseTrimmedString(nameRaw)
213			if err != nil {
214				return nil, err
215			}
216			cpu, err := parseBoundedInt(cpuRaw, 64)
217			if err != nil || cpu < 0 {
218				return nil, ErrInvalidPlacementInput
219			}
220			memory, err := parseBoundedInt(memoryRaw, 64)
221			if err != nil || memory < 0 {
222				return nil, ErrInvalidPlacementInput
223			}
224			labels := map[string]string{}
225			if labelRaw, ok := obj["labels"]; ok {
226				labels, err = parseStringMap(labelRaw)
227				if err != nil {
228					return nil, err
229				}
230			}
231			if names[name] {
232				return nil, ErrInvalidPlacementInput
233			}
234			names[name] = true
235			nodes = append(nodes, store.Node{Name: name, CPU: cpu, Memory: memory, Labels: labels})
236		}
237		if _, err := dec.Token(); err != nil {
238			return nil, ErrInvalidPlacementInput // closing ']'
239		}
240		return nodes, nil
241	}
242	
243	// parseStrictObject decodes an object whose member names are restricted to
244	// allowed. Both unknown and duplicate names are rejected.
245	func parseStrictObject(raw json.RawMessage, allowed map[string]bool) (map[string]json.RawMessage, error) {
246		if isNull(raw) {
247			return nil, ErrInvalidPlacementInput
248		}
249		dec := json.NewDecoder(bytes.NewReader(raw))
250		tok, err := dec.Token()
251		if err != nil {
252			return nil, ErrInvalidPlacementInput
253		}
254		if d, ok := tok.(json.Delim); !ok || d != '{' {
255			return nil, ErrInvalidPlacementInput
256		}
257		return readObjectMembers(dec, allowed)
258	}
259	
260	// parseStringMap decodes an object with arbitrary string keys and string
261	// values; null or non-string values are rejected.
262	func parseStringMap(raw json.RawMessage) (map[string]string, error) {
263		if isNull(raw) {
264			return nil, ErrInvalidPlacementInput
265		}
266		dec := json.NewDecoder(bytes.NewReader(raw))
267		tok, err := dec.Token()
268		if err != nil {
269			return nil, ErrInvalidPlacementInput
270		}
271		if d, ok := tok.(json.Delim); !ok || d != '{' {
272			return nil, ErrInvalidPlacementInput
273		}
274	
275		out := map[string]string{}
276		raws, err := readObjectMembers(dec, nil)
277		if err != nil {
278			return nil, err
279		}
280		for key, value := range raws {
281			s, err := parseJSONString(value)
282			if err != nil {
283				return nil, err
284			}
285			out[key] = s
286		}
287		return out, nil
288	}
289	
290	func readObjectMembers(dec *json.Decoder, allowed map[string]bool) (map[string]json.RawMessage, error) {
291		out := map[string]json.RawMessage{}
292		for dec.More() {
293			keyTok, err := dec.Token()
294			if err != nil {
295				return nil, ErrInvalidPlacementInput
296			}
297			key, ok := keyTok.(string)
298			if !ok {
299				return nil, ErrInvalidPlacementInput
300			}
301			if allowed != nil && !allowed[key] {
302				return nil, ErrInvalidPlacementInput
303			}
304			if _, dup := out[key]; dup {
305				return nil, ErrInvalidPlacementInput
306			}
307			var value json.RawMessage
308			if err := dec.Decode(&value); err != nil {
309				return nil, ErrInvalidPlacementInput
310			}
311			out[key] = value
312		}
313		if _, err := dec.Token(); err != nil {
314			return nil, ErrInvalidPlacementInput // closing '}'
315		}
316		return out, nil
317	}
318	
319	// parseTrimmedString accepts a JSON string that is non-empty and has no
320	// leading or trailing Unicode whitespace.
321	func parseTrimmedString(raw json.RawMessage) (string, error) {
322		s, err := parseJSONString(raw)
323		if err != nil {
324			return "", err
325		}
326		if s == "" || s != strings.TrimSpace(s) {
327			return "", ErrInvalidPlacementInput
328		}
329		return s, nil
330	}
331	
332	func parseJSONString(raw json.RawMessage) (string, error) {
333		if isNull(raw) {
334			return "", ErrInvalidPlacementInput
335		}
336		var s string
337		if err := json.Unmarshal(raw, &s); err != nil {
338			return "", ErrInvalidPlacementInput
339		}
340		return s, nil
341	}
342	
343	// parseBoundedInt accepts an integral JSON number without fraction or exponent
344	// that fits a signed integer of the given bit size (32 or 64).
345	func parseBoundedInt(raw json.RawMessage, bitSize int) (int64, error) {
346		if isNull(raw) {
347			return 0, ErrInvalidPlacementInput
348		}
349		dec := json.NewDecoder(bytes.NewReader(raw))
350		dec.UseNumber()
351		var value any
352		if err := dec.Decode(&value); err != nil {
353			return 0, ErrInvalidPlacementInput
354		}
355		number, ok := value.(json.Number)
356		if !ok {
357			return 0, ErrInvalidPlacementInput
358		}
359		n, err := strconv.ParseInt(number.String(), 10, bitSize)
360		if err != nil {
361			return 0, ErrInvalidPlacementInput
362		}
363		return n, nil
364	}
365	
366	func isNull(raw json.RawMessage) bool {
367		return bytes.Equal(bytes.TrimSpace(raw), []byte("null"))
368	}
