	second := `{
	  "resources": {"cpu": 100, "memory": 64},
	  "priority": 1, "queue": "q", "name": "job", "namespace": "ns",
	  "selector": {},
	  "nodes": [{"labels": {}, "memory": 128, "cpu": 200, "name": "n"}]
