1	// Package service implements placement acceptance: the trial scheduling
2	// decision together with idempotent, conflict-aware registration. Accept is
3	// the single business entry point for a parsed placement request; it has no
4	// dependency on the HTTP transport.
5	package service
6	
7	import (
8		"context"
9		"errors"
10		"fmt"
11	
12		"github.com/Bob-xisuke/orb-scheduler-core/internal/store"
13	)
14	
15	// Scheduling outcomes recorded on every placement.
16	const (
17		StatusPlaced   = "placed"
18		StatusRejected = "rejected"
19		ReasonNoNode   = "no_eligible_node"
20	)
21	
22	// Outcome classifies what Accept did with a submission.
23	type Outcome int
24	
25	const (
26		// Created means the (namespace, name) identity was registered for the
27		// first time by this call.
28		Created Outcome = iota
29		// Identical means the identity already existed with the same request
30		// content; the returned record is the original one.
31		Identical
32		// Conflict means the identity already existed with different content;
33		// the returned record is the untouched original.
34		Conflict
35	)
36	
37	// ErrStorageUnavailable is the sentinel wrapped for every persistence failure.
38	var ErrStorageUnavailable = errors.New("storage unavailable")
39	
40	// Service holds the collaborators needed to accept placements.
41	type Service struct {
42		st *store.Store
43	}
44	
45	// New builds the acceptance service over a store.
46	func New(st *store.Store) *Service {
47		return &Service{st: st}
48	}
49	
50	// Accept runs the trial placement and registers its result under the
51	// (namespace, name) identity. The first valid submission for an identity is
52	// stored and reported as Created; a later submission carrying the same request
53	// content is reported as Identical with the original record; one carrying
54	// different content is reported as Conflict and never changes the stored
55	// record. Scheduling results alone do not count as equal content. Input
56	// validation is expected to have happened before this call.
57	func (s *Service) Accept(ctx context.Context, p *store.Placement) (*store.Placement, Outcome, error) {
58		normalize(p)
59		p.Status, p.Node, p.Reason = schedule(p)
60	
61		stored, created, err := s.st.Submit(ctx, p)
62		if err != nil {
63			return nil, Created, storageError(err)
64		}
65		if created {
66			return stored, Created, nil
67		}
68	
69		same, err := store.SameInput(p, stored)
70		if err != nil {
71			return nil, Created, storageError(err)
72		}
73		if !same {
74			return stored, Conflict, nil
75		}
76		return stored, Identical, nil
77	}
78	
79	func storageError(err error) error {
80		return fmt.Errorf("accept placement: %w: %w", ErrStorageUnavailable, err)
81	}
82	
83	// normalize fills the documented defaults so the entry point behaves the same
84	// regardless of how the request was assembled: an omitted selector or node
85	// labels map is an empty object. It does not touch the candidate array's
86	// order, which is significant for content comparison.
87	func normalize(p *store.Placement) {
88		if p.Selector == nil {
89			p.Selector = map[string]string{}
90		}
91		if p.Nodes == nil {
92			p.Nodes = []store.Node{}
93		}
94		for i := range p.Nodes {
95			if p.Nodes[i].Labels == nil {
96				p.Nodes[i].Labels = map[string]string{}
97			}
98		}
99	}
100

