		if err != nil {
			return nil, err
		}
		cpu, err := parseBoundedInt(cpuRaw, 64)
		if err != nil || cpu < 0 {
			return nil, ErrInvalidPlacementInput
		}
		memory, err := parseBoundedInt(memoryRaw, 64)
		if err != nil || memory < 0 {
			return nil, ErrInvalidPlacementInput
		}
